export const INSTALL_BAT      = "@echo off\nsetlocal enabledelayedexpansion\n\nset \"MQ=%APPDATA%\\MetaQuotes\\Terminal\"\n\necho ============================================\necho   MT4/MT5 ReportExporter Setup\necho ============================================\necho.\n\nREM --- Check MetaQuotes folder exists ---\nif not exist \"%MQ%\" (\n    echo ERROR: MetaTrader not found.\n    echo Launch MT4 or MT5 once, then run this script again.\n    echo.\n    pause & exit /b 1\n)\n\nREM --- Pre-create MTExport output folder ---\nmkdir \"%USERPROFILE%\\MTExport\" 2>nul\n\nREM --- Get actual Desktop path (handles OneDrive redirection) ---\nset \"DESKTOP=\"\nfor /f \"tokens=2,*\" %%A in ('reg query \"HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Shell Folders\" /v Desktop 2^>nul') do set \"DESKTOP=%%B\"\nif not defined DESKTOP set \"DESKTOP=%USERPROFILE%\\Desktop\"\nset \"BAT=!DESKTOP!\\MT_Exporter.bat\"\n\nREM --- Initialize launcher batch ---\n(\n    echo @echo off\n) > \"!BAT!\"\n\nset COUNT=0\n\nfor /d %%D in (\"%MQ%\\*\") do (\n    if exist \"%%D\\origin.txt\" (\n\n        REM --- Read install path from origin.txt ---\n        set \"BASEPATH=\"\n        for /f \"tokens=* delims=\" %%L in ('type \"%%D\\origin.txt\"') do (\n            if not defined BASEPATH set \"BASEPATH=%%L\"\n        )\n\n        if defined BASEPATH (\n            if exist \"!BASEPATH!\\\" (\n\n                REM --- Detect MT4 vs MT5 by executable name ---\n                set \"EXE=\"\n                set \"MQLDIR=\"\n                set \"EAFILE=\"\n                set \"MQVER=\"\n\n                if exist \"!BASEPATH!\\terminal64.exe\" (\n                    set \"EXE=!BASEPATH!\\terminal64.exe\"\n                    set \"MQLDIR=MQL5\"\n                    set \"EAFILE=MT5ReportExporter.mq5\"\n                    set \"MQVER=MT5\"\n                ) else if exist \"!BASEPATH!\\terminal.exe\" (\n                    set \"EXE=!BASEPATH!\\terminal.exe\"\n                    set \"MQLDIR=MQL4\"\n                    set \"EAFILE=MT4ReportExporter.mq4\"\n                    set \"MQVER=MT4\"\n                )\n\n                if defined EXE (\n                    if exist \"%~dp0!EAFILE!\" (\n\n                        REM --- Copy EA to Experts folder ---\n                        mkdir \"%%D\\!MQLDIR!\" 2>nul\n                        mkdir \"%%D\\!MQLDIR!\\Experts\" 2>nul\n                        copy /y \"%~dp0!EAFILE!\" \"%%D\\!MQLDIR!\\Experts\\!EAFILE!\" >nul 2>&1\n\n                        if exist \"%%D\\!MQLDIR!\\Experts\\!EAFILE!\" (\n                            echo      EA copy  : OK\n                        ) else (\n                            echo      EA copy  : FAILED\n                        )\n\n                        REM --- Compile EA with MetaEditor ---\n                        set \"METAED=\"\n                        if exist \"!BASEPATH!\\metaeditor64.exe\" set \"METAED=!BASEPATH!\\metaeditor64.exe\"\n                        if exist \"!BASEPATH!\\metaeditor.exe\"   set \"METAED=!BASEPATH!\\metaeditor.exe\"\n                        if defined METAED (\n                            \"!METAED!\" /compile:\"%%D\\!MQLDIR!\\Experts\\!EAFILE!\" /log\n                            echo      EA compile: OK\n                        ) else (\n                            echo      EA compile: SKIPPED ^(MetaEditor not found^)\n                        )\n\n                        REM --- Create MTExporter profile directory ---\n                        mkdir \"%%D\\profiles\" 2>nul\n                        mkdir \"%%D\\profiles\\charts\" 2>nul\n                        mkdir \"%%D\\profiles\\charts\\MTExporter\" 2>nul\n\n                        REM --- Copy charts from any existing profile ---\n                        set \"COPIED=0\"\n                        for /d %%P in (\"%%D\\profiles\\charts\\*\") do (\n                            if /i not \"%%~nxP\"==\"MTExporter\" if \"!COPIED!\"==\"0\" (\n                                if exist \"%%P\\*.chr\" (\n                                    copy /y \"%%P\\*.chr\" \"%%D\\profiles\\charts\\MTExporter\\\" >nul 2>&1\n                                    set \"COPIED=1\"\n                                )\n                            )\n                        )\n\n                        REM --- Add to launcher bat ---\n                        (\n                            echo start \"\" \"!EXE!\" /profile:MTExporter\n                        ) >> \"!BAT!\"\n\n                        set /a COUNT+=1\n                        echo [!COUNT!] [!MQVER!] !EXE!\n                        echo.\n\n                    ) else (\n                        echo      SKIP: !EAFILE! not found next to install.bat\n                    )\n                )\n            )\n        )\n    )\n)\n\nif !COUNT! gtr 0 (\n    echo ============================================\n    echo   Launching for one-time profile setup\n    echo ============================================\n    echo.\n\n    REM --- Close any running terminals before setup launch ---\n    taskkill /im terminal.exe   2>nul\n    taskkill /im terminal64.exe 2>nul\n    timeout /t 5 /nobreak >nul\n\n    for /d %%D in (\"%MQ%\\*\") do (\n        if exist \"%%D\\origin.txt\" (\n            set \"BASEPATH=\"\n            for /f \"tokens=* delims=\" %%L in ('type \"%%D\\origin.txt\"') do (\n                if not defined BASEPATH set \"BASEPATH=%%L\"\n            )\n            if defined BASEPATH if exist \"!BASEPATH!\\\" (\n                set \"EXE=\"\n                set \"EAFILE=\"\n                if exist \"!BASEPATH!\\terminal64.exe\" (\n                    set \"EXE=!BASEPATH!\\terminal64.exe\"\n                    set \"EAFILE=MT5ReportExporter\"\n                ) else if exist \"!BASEPATH!\\terminal.exe\" (\n                    set \"EXE=!BASEPATH!\\terminal.exe\"\n                    set \"EAFILE=MT4ReportExporter\"\n                )\n                if defined EXE (\n                    start \"\" \"!EXE!\" /profile:MTExporter /expert:!EAFILE!\n                )\n            )\n        )\n    )\n\n    echo For EACH terminal window that opens:\n    echo   1. Wait for it to fully load\n    echo   2. Drag the ReportExporter EA onto any chart\n    echo   3. Click OK in the EA settings dialog\n    echo   4. File -^> Profiles -^> Save As... -^> type: MTExporter -^> OK\n    echo   5. Close the terminal ^(File -^> Exit^)\n    echo.\n    echo After doing this for ALL windows, setup is complete.\n    echo Use MT_Exporter.bat on Desktop for all future launches.\n)\n\necho ============================================\nif !COUNT!==0 (\n    echo No MT4/MT5 installation found.\n    echo Launch MT4 or MT5 once, then run this script again.\n    echo Make sure MT4ReportExporter.mq4 and/or\n    echo MT5ReportExporter.mq5 are in the same folder.\n) else (\n    echo Setup complete ^(!COUNT! instance^(s^)^)\n    echo Launcher: !BAT!\n)\necho ============================================\necho.\npause\n"
export const MQ4_CONTENT      = "//+------------------------------------------------------------------+\n//|  MT4ReportExporter.mq4                                           |\n//|  取引履歴を JSON に自動エクスポートする EA                        |\n//|                                                                  |\n//|  【特徴】                                                        |\n//|  ・自動売買（Auto Trading）が OFF でも動作します                  |\n//|  ・注文・決済などの売買操作は一切行いません                      |\n//|  ・ファイル書き出しのみ実行します                                |\n//|  ・ブラウザの「更新」ボタンで即時エクスポートに対応              |\n//|                                                                  |\n//|  【設置方法】                                                    |\n//|  1. MQL4\\Experts\\ フォルダにコピー                               |\n//|  2. MT4_Exporter.bat で MT4 を起動                               |\n//|  3. ダイアログで OK を押す（自動売買許可は不要）                 |\n//|                                                                  |\n//|  【出力先】                                                      |\n//|  %USERPROFILE%\\MTExport\\                                        |\n//|  mt4_report_<口座番号>.json                                      |\n//+------------------------------------------------------------------+\n#property copyright \"\"\n#property link      \"\"\n#property version   \"1.50\"\n#property strict\n#property description \"取引履歴を JSON へ自動エクスポートします。自動売買 OFF でも動作します。\"\n\n#import \"kernel32.dll\"\n   int  GetEnvironmentVariableW(string name, ushort &buf[], int bufSize);\n   int  CreateDirectoryW(string path, int sec);\n   int  CreateFileW(string path, uint access, uint share, int sec,\n                    uint disp, uint flags, int tmpl);\n   bool WriteFile(int hFile, uchar &buf[], uint toWrite, uint &written[], int overlapped);\n   bool CloseHandle(int hFile);\n   bool DeleteFileW(string path);\n#import\n\n#define GENERIC_WRITE         0x40000000\n#define GENERIC_READ          0x80000000\n#define CREATE_ALWAYS         2\n#define OPEN_EXISTING         3\n#define FILE_ATTRIBUTE_NORMAL 0x80\n#define FILE_SHARE_READ       1\n\ninput int    RefreshMinutes  = 1;            // 定期エクスポート間隔（分）\ninput int    RealtimeSec     = 10;           // Tick 発生時の最小エクスポート間隔（秒）\ninput string ExportSubFolder = \"MTExport\";  // USERPROFILE 直下のサブフォルダ名\n\n// タイマー間隔（秒）: トリガーファイルをこの間隔でチェックする\n#define TIMER_SEC 5\n\nint      g_ExportTick        = 0; // TIMER_SEC 単位のカウンター\ndatetime g_LastTriggerExport = 0; // 直近のトリガー発火時刻（二重発火防止）\ndatetime g_LastRealtimeExport = 0; // 直近の Tick エクスポート時刻\n\n//+------------------------------------------------------------------+\nint OnInit()\n{\n   EventSetTimer(TIMER_SEC);\n   ExportTrades();\n   return INIT_SUCCEEDED;\n}\n\nvoid OnDeinit(const int reason) { EventKillTimer(); }\n\nvoid OnTick()\n{\n   datetime now = TimeCurrent();\n   int sec = MathMax(RealtimeSec, 5);\n   if (now - g_LastRealtimeExport >= sec)\n   {\n      g_LastRealtimeExport = now;\n      g_ExportTick = 0; // 定期タイマーもリセット（二重エクスポート防止）\n      ExportTrades();\n   }\n}\n\nvoid OnTimer()\n{\n   // ブラウザからの即時エクスポート要求をチェック\n   bool triggered = CheckTrigger();\n\n   g_ExportTick++;\n   // triggered の場合、または定期インターバルに達した場合にエクスポート\n   if (triggered || g_ExportTick >= (RefreshMinutes * 60 / TIMER_SEC))\n   {\n      g_ExportTick = 0;\n      ExportTrades();\n   }\n}\n\n//+------------------------------------------------------------------+\n//|  トリガーファイル（_refresh.cmd）を確認する                      |\n//|  ブラウザが書き込むと即時エクスポートが発動する                  |\n//|  ファイルの削除はブラウザ側が行う（全インスタンス対応のため）    |\n//+------------------------------------------------------------------+\nbool CheckTrigger()\n{\n   string triggerPath = GetExportDir() + \"\\\\_refresh.cmd\";\n   int h = CreateFileW(triggerPath, GENERIC_READ, FILE_SHARE_READ, 0,\n                       OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, 0);\n   if (h == -1) return false;\n   CloseHandle(h);\n\n   // 30秒以内の二重発火を防ぐ\n   datetime now = TimeCurrent();\n   if (now - g_LastTriggerExport < 30) return false;\n   g_LastTriggerExport = now;\n   return true;\n}\n\n//+------------------------------------------------------------------+\nstring GetExportDir()\n{\n   ushort buf[260];\n   int len = GetEnvironmentVariableW(\"USERPROFILE\", buf, 260);\n   if (len <= 0) return \"\";\n   return ShortArrayToString(buf, 0, len) + \"\\\\\" + ExportSubFolder;\n}\n\nbool WriteStringToFile(string filepath, string content)\n{\n   uchar buf[];\n   int len = StringToCharArray(content, buf, 0, StringLen(content));\n   if (len <= 0) return false;\n\n   uint written[1];\n   int hFile = CreateFileW(filepath, GENERIC_WRITE, 0, 0, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, 0);\n   if (hFile == -1) return false;\n\n   bool ok = WriteFile(hFile, buf, (uint)len, written, 0);\n   CloseHandle(hFile);\n   return ok;\n}\n\n//+------------------------------------------------------------------+\n//|  取引履歴を JSON ファイルに書き出す                              |\n//+------------------------------------------------------------------+\nvoid ExportTrades()\n{\n   string exportDir = GetExportDir();\n   if (exportDir == \"\")\n   {\n      Print(\"[MTExporter] USERPROFILE が取得できません\");\n      return;\n   }\n\n   CreateDirectoryW(exportDir, 0);\n\n   string filepath = exportDir + \"\\\\mt4_report_\" + IntegerToString(AccountNumber()) + \".json\";\n\n   string json = \"{\\n\";\n   json += \"  \\\"account\\\": \"     + IntegerToString(AccountNumber())     + \",\\n\";\n   json += \"  \\\"name\\\": \\\"\"      + EscapeJson(AccountName())            + \"\\\",\\n\";\n   json += \"  \\\"server\\\": \\\"\"    + EscapeJson(AccountServer())          + \"\\\",\\n\";\n   json += \"  \\\"currency\\\": \\\"\"  + AccountCurrency()                    + \"\\\",\\n\";\n   json += \"  \\\"balance\\\": \"     + DoubleToString(AccountBalance(), 2)  + \",\\n\";\n   json += \"  \\\"equity\\\": \"      + DoubleToString(AccountEquity(),  2)  + \",\\n\";\n   json += \"  \\\"credit\\\": \"      + DoubleToString(AccountCredit(),  2)  + \",\\n\";\n   json += \"  \\\"leverage\\\": \"    + IntegerToString(AccountLeverage())   + \",\\n\";\n   json += \"  \\\"exportTime\\\": \\\"\"+ TimeToISO(TimeCurrent())             + \"\\\",\\n\";\n   json += \"  \\\"autoTrading\\\": \" + ((bool)TerminalInfoInteger(TERMINAL_TRADE_ALLOWED) ? \"true\" : \"false\") + \",\\n\";\n   json += \"  \\\"trades\\\": [\\n\";\n\n   int total = OrdersHistoryTotal();\n   bool first = true;\n\n   for (int i = 0; i < total; i++)\n   {\n      if (!OrderSelect(i, SELECT_BY_POS, MODE_HISTORY)) continue;\n      if (OrderType() > OP_SELL) continue;\n\n      if (!first) json += \",\\n\";\n      first = false;\n\n      string typeStr    = (OrderType() == OP_BUY) ? \"buy\" : \"sell\";\n      double profit     = OrderProfit();\n      double swap       = OrderSwap();\n      double commission = OrderCommission();\n\n      json += \"    {\";\n      json += \"\\\"ticket\\\":\"      + IntegerToString(OrderTicket())             + \",\";\n      json += \"\\\"openTime\\\":\\\"\"  + TimeToISO(OrderOpenTime())                 + \"\\\",\";\n      json += \"\\\"closeTime\\\":\\\"\" + TimeToISO(OrderCloseTime())                + \"\\\",\";\n      json += \"\\\"type\\\":\\\"\"      + typeStr                                    + \"\\\",\";\n      json += \"\\\"size\\\":\"        + DoubleToString(OrderLots(),       2)       + \",\";\n      json += \"\\\"symbol\\\":\\\"\"    + OrderSymbol()                              + \"\\\",\";\n      json += \"\\\"openPrice\\\":\"   + DoubleToString(OrderOpenPrice(),  5)       + \",\";\n      json += \"\\\"closePrice\\\":\"  + DoubleToString(OrderClosePrice(), 5)       + \",\";\n      json += \"\\\"sl\\\":\"          + DoubleToString(OrderStopLoss(),   5)       + \",\";\n      json += \"\\\"tp\\\":\"          + DoubleToString(OrderTakeProfit(), 5)       + \",\";\n      json += \"\\\"commission\\\":\"  + DoubleToString(commission,        2)       + \",\";\n      json += \"\\\"swap\\\":\"        + DoubleToString(swap,              2)       + \",\";\n      json += \"\\\"profit\\\":\"      + DoubleToString(profit,            2)       + \",\";\n      json += \"\\\"netProfit\\\":\"   + DoubleToString(profit+swap+commission, 2)  + \",\";\n      json += \"\\\"comment\\\":\\\"\"   + EscapeJson(OrderComment())                 + \"\\\"\";\n      json += \"}\";\n   }\n\n   json += \"\\n  ],\\n\";\n   json += \"  \\\"positions\\\": [\\n\";\n\n   int openTotal = OrdersTotal();\n   bool firstPos = true;\n   for (int i = 0; i < openTotal; i++)\n   {\n      if (!OrderSelect(i, SELECT_BY_POS, MODE_TRADES)) continue;\n      if (OrderType() > OP_SELL) continue;\n\n      if (!firstPos) json += \",\\n\";\n      firstPos = false;\n\n      string posType = (OrderType() == OP_BUY) ? \"buy\" : \"sell\";\n      json += \"    {\";\n      json += \"\\\"ticket\\\":\"       + IntegerToString(OrderTicket())             + \",\";\n      json += \"\\\"openTime\\\":\\\"\"   + TimeToISO(OrderOpenTime())                 + \"\\\",\";\n      json += \"\\\"type\\\":\\\"\"       + posType                                    + \"\\\",\";\n      json += \"\\\"size\\\":\"         + DoubleToString(OrderLots(),       2)       + \",\";\n      json += \"\\\"symbol\\\":\\\"\"     + OrderSymbol()                              + \"\\\",\";\n      json += \"\\\"openPrice\\\":\"    + DoubleToString(OrderOpenPrice(),  5)       + \",\";\n      json += \"\\\"currentPrice\\\":\" + DoubleToString(OrderClosePrice(), 5)       + \",\";\n      json += \"\\\"sl\\\":\"           + DoubleToString(OrderStopLoss(),   5)       + \",\";\n      json += \"\\\"tp\\\":\"           + DoubleToString(OrderTakeProfit(), 5)       + \",\";\n      json += \"\\\"profit\\\":\"       + DoubleToString(OrderProfit(),     2)       + \",\";\n      json += \"\\\"swap\\\":\"         + DoubleToString(OrderSwap(),       2)       + \",\";\n      json += \"\\\"comment\\\":\\\"\"    + EscapeJson(OrderComment())                 + \"\\\"\";\n      json += \"}\";\n   }\n\n   json += \"\\n  ]\\n}\\n\";\n\n   if (WriteStringToFile(filepath, json))\n      Print(\"[MTExporter] エクスポート完了: \", filepath, \"  (\", total, \" 件, \", openTotal, \" positions)\");\n   else\n      Print(\"[MTExporter] 書き込み失敗: \", filepath, \"  エラー: \", GetLastError());\n}\n\n//+------------------------------------------------------------------+\nstring EscapeJson(string s)\n{\n   StringReplace(s, \"\\\\\", \"\\\\\\\\\");\n   StringReplace(s, \"\\\"\", \"\\\\\\\"\");\n   StringReplace(s, \"\\n\", \"\\\\n\");\n   StringReplace(s, \"\\r\", \"\\\\r\");\n   StringReplace(s, \"\\t\", \"\\\\t\");\n   return s;\n}\n\nstring TimeToISO(datetime t)\n{\n   if (t == 0) return \"\";\n   return TimeToString(t, TIME_DATE | TIME_SECONDS);\n}\n"
export const MQ5_CONTENT      = "//+------------------------------------------------------------------+\n//|  MT5ReportExporter.mq5                                           |\n//|  取引履歴を JSON に自動エクスポートする EA (MT5版)                |\n//|                                                                  |\n//|  【特徴】                                                        |\n//|  ・自動売買（Auto Trading）が OFF でも動作します                  |\n//|  ・注文・決済などの売買操作は一切行いません                      |\n//|  ・ファイル書き出しのみ実行します                                |\n//|  ・ブラウザの「更新」ボタンで即時エクスポートに対応              |\n//|                                                                  |\n//|  【出力先】                                                      |\n//|  %USERPROFILE%\\MTExport\\                                        |\n//|  mt4_report_<口座番号>.json  (MT4 と同じ形式)                    |\n//+------------------------------------------------------------------+\n#property copyright \"\"\n#property link      \"\"\n#property version   \"1.10\"\n#property description \"取引履歴を JSON へ自動エクスポートします。自動売買 OFF でも動作します。\"\n\n#import \"kernel32.dll\"\n   int  GetEnvironmentVariableW(string name, ushort &buf[], int bufSize);\n   int  CreateDirectoryW(string path, long sec);\n   long CreateFileW(string path, uint access, uint share, long sec,\n                    uint disp, uint flags, long tmpl);\n   bool WriteFile(long hFile, uchar &buf[], uint toWrite, uint &written[], long overlapped);\n   bool CloseHandle(long hFile);\n#import\n\n#define GENERIC_WRITE         0x40000000\n#define GENERIC_READ          0x80000000\n#define CREATE_ALWAYS         2\n#define OPEN_EXISTING         3\n#define FILE_ATTRIBUTE_NORMAL 0x80\n#define FILE_SHARE_READ       1\n\ninput int    RefreshMinutes  = 1;           // 定期エクスポート間隔（分）\ninput int    RealtimeSec     = 10;          // Tick 発生時の最小エクスポート間隔（秒）\ninput string ExportSubFolder = \"MTExport\"; // USERPROFILE 直下のサブフォルダ名\n\n#define TIMER_SEC 5\n\nint      g_ExportTick         = 0;\ndatetime g_LastTriggerExport  = 0;\ndatetime g_LastRealtimeExport = 0;\n\n//+------------------------------------------------------------------+\nint OnInit()\n{\n   EventSetTimer(TIMER_SEC);\n   ExportTrades();\n   return INIT_SUCCEEDED;\n}\n\nvoid OnDeinit(const int reason) { EventKillTimer(); }\n\nvoid OnTick()\n{\n   datetime now = TimeCurrent();\n   int sec = MathMax(RealtimeSec, 5);\n   if (now - g_LastRealtimeExport >= sec)\n   {\n      g_LastRealtimeExport = now;\n      g_ExportTick = 0;\n      ExportTrades();\n   }\n}\n\nvoid OnTimer()\n{\n   bool triggered = CheckTrigger();\n   g_ExportTick++;\n   if (triggered || g_ExportTick >= (RefreshMinutes * 60 / TIMER_SEC))\n   {\n      g_ExportTick = 0;\n      ExportTrades();\n   }\n}\n\n//+------------------------------------------------------------------+\n//|  トリガーファイル（_refresh.cmd）を確認する                      |\n//+------------------------------------------------------------------+\nbool CheckTrigger()\n{\n   string triggerPath = GetExportDir() + \"\\\\_refresh.cmd\";\n   long h = CreateFileW(triggerPath, GENERIC_READ, FILE_SHARE_READ, 0,\n                        OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, 0);\n   if (h == -1) return false;\n   CloseHandle(h);\n\n   datetime now = TimeCurrent();\n   if (now - g_LastTriggerExport < 30) return false;\n   g_LastTriggerExport = now;\n   return true;\n}\n\n//+------------------------------------------------------------------+\nstring GetExportDir()\n{\n   ushort buf[260];\n   int len = GetEnvironmentVariableW(\"USERPROFILE\", buf, 260);\n   if (len <= 0) return \"\";\n   return ShortArrayToString(buf, 0, len) + \"\\\\\" + ExportSubFolder;\n}\n\n//+------------------------------------------------------------------+\nbool WriteStringToFile(string filepath, string content)\n{\n   uchar buf[];\n   int len = StringToCharArray(content, buf, 0, StringLen(content));\n   if (len <= 0) return false;\n\n   uint written[];\n   ArrayResize(written, 1);\n   long hFile = CreateFileW(filepath, GENERIC_WRITE, 0, 0, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, 0);\n   if (hFile == -1) return false;\n\n   bool ok = WriteFile(hFile, buf, (uint)len, written, 0);\n   CloseHandle(hFile);\n   return ok;\n}\n\n//+------------------------------------------------------------------+\nstring EscapeJson(string s)\n{\n   StringReplace(s, \"\\\\\", \"\\\\\\\\\");\n   StringReplace(s, \"\\\"\", \"\\\\\\\"\");\n   StringReplace(s, \"\\n\", \"\\\\n\");\n   StringReplace(s, \"\\r\", \"\\\\r\");\n   StringReplace(s, \"\\t\", \"\\\\t\");\n   return s;\n}\n\n//+------------------------------------------------------------------+\nstring TimeToISO(datetime t)\n{\n   if (t == 0) return \"\";\n   MqlDateTime dt;\n   TimeToStruct(t, dt);\n   return StringFormat(\"%04d-%02d-%02d %02d:%02d:%02d\",\n                       dt.year, dt.mon, dt.day, dt.hour, dt.min, dt.sec);\n}\n\n//+------------------------------------------------------------------+\n//|  取引履歴を JSON ファイルに書き出す                              |\n//|  OUT/INOUT ディールを起点に IN ディールを position ID で検索し   |\n//|  MT4 と同形式の完結したトレードレコードを出力する                |\n//+------------------------------------------------------------------+\nvoid ExportTrades()\n{\n   string exportDir = GetExportDir();\n   if (exportDir == \"\")\n   {\n      Print(\"[MT5Exporter] USERPROFILE が取得できません\");\n      return;\n   }\n\n   CreateDirectoryW(exportDir, 0);\n\n   long   accountNumber = AccountInfoInteger(ACCOUNT_LOGIN);\n   string filepath = exportDir + \"\\\\mt4_report_\" + IntegerToString(accountNumber) + \".json\";\n\n   HistorySelect(0, TimeCurrent() + 1);\n   int total = HistoryDealsTotal();\n\n   string json = \"{\\n\";\n   json += \"  \\\"account\\\": \"      + IntegerToString(accountNumber)                         + \",\\n\";\n   json += \"  \\\"name\\\": \\\"\"       + EscapeJson(AccountInfoString(ACCOUNT_NAME))            + \"\\\",\\n\";\n   json += \"  \\\"server\\\": \\\"\"     + EscapeJson(AccountInfoString(ACCOUNT_SERVER))          + \"\\\",\\n\";\n   json += \"  \\\"currency\\\": \\\"\"   + AccountInfoString(ACCOUNT_CURRENCY)                   + \"\\\",\\n\";\n   json += \"  \\\"balance\\\": \"      + DoubleToString(AccountInfoDouble(ACCOUNT_BALANCE), 2)  + \",\\n\";\n   json += \"  \\\"equity\\\": \"       + DoubleToString(AccountInfoDouble(ACCOUNT_EQUITY),  2)  + \",\\n\";\n   json += \"  \\\"credit\\\": \"       + DoubleToString(AccountInfoDouble(ACCOUNT_CREDIT),  2)  + \",\\n\";\n   json += \"  \\\"leverage\\\": \"     + IntegerToString(AccountInfoInteger(ACCOUNT_LEVERAGE))  + \",\\n\";\n   json += \"  \\\"exportTime\\\": \\\"\" + TimeToISO(TimeCurrent())                              + \"\\\",\\n\";\n   json += \"  \\\"autoTrading\\\": \" + ((bool)TerminalInfoInteger(TERMINAL_TRADE_ALLOWED) ? \"true\" : \"false\") + \",\\n\";\n   json += \"  \\\"trades\\\": [\\n\";\n\n   bool first = true;\n\n   for (int i = 0; i < total; i++)\n   {\n      ulong outTicket = HistoryDealGetTicket(i);\n      if (outTicket == 0) continue;\n\n      ENUM_DEAL_ENTRY outEntry = (ENUM_DEAL_ENTRY)HistoryDealGetInteger(outTicket, DEAL_ENTRY);\n      if (outEntry != DEAL_ENTRY_OUT && outEntry != DEAL_ENTRY_INOUT) continue;\n\n      ENUM_DEAL_TYPE dealType = (ENUM_DEAL_TYPE)HistoryDealGetInteger(outTicket, DEAL_TYPE);\n      if (dealType != DEAL_TYPE_BUY && dealType != DEAL_TYPE_SELL) continue;\n\n      string   typeStr    = (dealType == DEAL_TYPE_BUY) ? \"buy\" : \"sell\";\n      double   closePrice = HistoryDealGetDouble(outTicket,  DEAL_PRICE);\n      double   volume     = HistoryDealGetDouble(outTicket,  DEAL_VOLUME);\n      string   symbol     = HistoryDealGetString(outTicket,  DEAL_SYMBOL);\n      datetime closeTime  = (datetime)HistoryDealGetInteger(outTicket, DEAL_TIME);\n      double   profit     = HistoryDealGetDouble(outTicket,  DEAL_PROFIT);\n      double   swap       = HistoryDealGetDouble(outTicket,  DEAL_SWAP);\n      double   commission = HistoryDealGetDouble(outTicket,  DEAL_COMMISSION);\n      string   comment    = HistoryDealGetString(outTicket,  DEAL_COMMENT);\n      ulong    posId      = (ulong)HistoryDealGetInteger(outTicket, DEAL_POSITION_ID);\n\n      // 対応する IN ディールをポジション ID で検索\n      datetime openTime  = closeTime;\n      double   openPrice = closePrice;\n      for (int j = 0; j < i; j++)\n      {\n         ulong inTicket = HistoryDealGetTicket(j);\n         if (inTicket == 0) continue;\n         if ((ulong)HistoryDealGetInteger(inTicket, DEAL_POSITION_ID) != posId) continue;\n         ENUM_DEAL_ENTRY inEntry = (ENUM_DEAL_ENTRY)HistoryDealGetInteger(inTicket, DEAL_ENTRY);\n         if (inEntry != DEAL_ENTRY_IN && inEntry != DEAL_ENTRY_INOUT) continue;\n         openTime   = (datetime)HistoryDealGetInteger(inTicket, DEAL_TIME);\n         openPrice  = HistoryDealGetDouble(inTicket, DEAL_PRICE);\n         commission += HistoryDealGetDouble(inTicket, DEAL_COMMISSION);\n         if (comment == \"\") comment = HistoryDealGetString(inTicket, DEAL_COMMENT);\n         break;\n      }\n\n      if (!first) json += \",\\n\";\n      first = false;\n\n      json += \"    {\";\n      json += \"\\\"ticket\\\":\"       + IntegerToString(outTicket)                       + \",\";\n      json += \"\\\"openTime\\\":\\\"\"   + TimeToISO(openTime)                             + \"\\\",\";\n      json += \"\\\"closeTime\\\":\\\"\" + TimeToISO(closeTime)                            + \"\\\",\";\n      json += \"\\\"type\\\":\\\"\"      + typeStr                                          + \"\\\",\";\n      json += \"\\\"size\\\":\"        + DoubleToString(volume, 2)                        + \",\";\n      json += \"\\\"symbol\\\":\\\"\"   + symbol                                            + \"\\\",\";\n      json += \"\\\"openPrice\\\":\"  + DoubleToString(openPrice, 5)                      + \",\";\n      json += \"\\\"closePrice\\\":\" + DoubleToString(closePrice, 5)                     + \",\";\n      json += \"\\\"sl\\\":0,\\\"tp\\\":0,\";\n      json += \"\\\"commission\\\":\"  + DoubleToString(commission, 2)                    + \",\";\n      json += \"\\\"swap\\\":\"        + DoubleToString(swap, 2)                          + \",\";\n      json += \"\\\"profit\\\":\"      + DoubleToString(profit, 2)                        + \",\";\n      json += \"\\\"netProfit\\\":\"   + DoubleToString(profit + swap + commission, 2)    + \",\";\n      json += \"\\\"comment\\\":\\\"\"  + EscapeJson(comment)                               + \"\\\"\";\n      json += \"}\";\n   }\n\n   json += \"\\n  ],\\n\";\n   json += \"  \\\"positions\\\": [\\n\";\n\n   int posTotal = PositionsTotal();\n   bool firstPos = true;\n   for (int i = 0; i < posTotal; i++)\n   {\n      ulong posTicket = PositionGetTicket(i);\n      if (posTicket == 0) continue;\n\n      ENUM_POSITION_TYPE posType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);\n      string typeStr = (posType == POSITION_TYPE_BUY) ? \"buy\" : \"sell\";\n\n      if (!firstPos) json += \",\\n\";\n      firstPos = false;\n\n      json += \"    {\";\n      json += \"\\\"ticket\\\":\"       + IntegerToString(posTicket)                                    + \",\";\n      json += \"\\\"openTime\\\":\\\"\"   + TimeToISO((datetime)PositionGetInteger(POSITION_TIME))        + \"\\\",\";\n      json += \"\\\"type\\\":\\\"\"       + typeStr                                                        + \"\\\",\";\n      json += \"\\\"size\\\":\"         + DoubleToString(PositionGetDouble(POSITION_VOLUME),       2)   + \",\";\n      json += \"\\\"symbol\\\":\\\"\"     + PositionGetString(POSITION_SYMBOL)                            + \"\\\",\";\n      json += \"\\\"openPrice\\\":\"    + DoubleToString(PositionGetDouble(POSITION_PRICE_OPEN),    5)  + \",\";\n      json += \"\\\"currentPrice\\\":\" + DoubleToString(PositionGetDouble(POSITION_PRICE_CURRENT), 5)  + \",\";\n      json += \"\\\"sl\\\":\"           + DoubleToString(PositionGetDouble(POSITION_SL),           5)   + \",\";\n      json += \"\\\"tp\\\":\"           + DoubleToString(PositionGetDouble(POSITION_TP),           5)   + \",\";\n      json += \"\\\"profit\\\":\"       + DoubleToString(PositionGetDouble(POSITION_PROFIT),       2)   + \",\";\n      json += \"\\\"swap\\\":\"         + DoubleToString(PositionGetDouble(POSITION_SWAP),         2)   + \",\";\n      json += \"\\\"comment\\\":\\\"\"    + EscapeJson(PositionGetString(POSITION_COMMENT))               + \"\\\"\";\n      json += \"}\";\n   }\n\n   json += \"\\n  ]\\n}\\n\";\n\n   if (WriteStringToFile(filepath, json))\n      Print(\"[MT5Exporter] エクスポート完了: \", filepath, \"  (\", total, \" deals, \", posTotal, \" positions)\");\n   else\n      Print(\"[MT5Exporter] 書き込み失敗: \", filepath, \"  エラー: \", GetLastError());\n}\n"
export const SYNC_PS1_CONTENT = "# sync-to-supabase.ps1\n# Upload MT4/MT5 JSON reports to Supabase (Realtime mode)\n#\n# Watches the MTExport folder and uploads immediately on file change.\n# Uses a mutex so only one instance runs at a time.\n# Task scheduler can keep calling every minute - extras exit instantly.\n#\n# Also polls Supabase for AutoTrading toggle commands (ea_controls where account_number=0)\n# and sends Ctrl+E to all running MetaTrader windows when the state changes.\n#\n# Usage A (direct):\n#   .\\sync-to-supabase.ps1 -Url \"https://xxxx.supabase.co\" -AnonKey \"eyJ...\" -Email \"you@example.com\" -Password \"pass\"\n#\n# Usage B (via run-sync.vbs, no args needed - credentials embedded in vbs):\n#   wscript run-sync.vbs\n\nparam(\n    [string]$Url      = '',\n    [string]$AnonKey  = '',\n    [string]$Email    = '',\n    [string]$Password = '',\n    [string]$Folder   = \"$env:USERPROFILE\\MTExport\"\n)\n\n$Url      = $Url.Trim()\n$AnonKey  = $AnonKey.Trim()\n$Email    = $Email.Trim()\n$Password = $Password.Trim()\n\nif (-not $Url -or -not $AnonKey -or -not $Email -or -not $Password) {\n    Write-Error \"Missing credentials. Provide -Url -AnonKey -Email -Password or use run-sync.vbs.\"\n    exit 1\n}\n\n# ── Single-instance guard ─────────────────────────────────────────\n$mutex = New-Object System.Threading.Mutex($false, \"Global\\MTExportSyncMutex\")\nif (-not $mutex.WaitOne(0)) {\n    exit 0\n}\n\n# ── Win32 API for AutoTrading toggle (Ctrl+E) ─────────────────────\nAdd-Type @\"\nusing System;\nusing System.Runtime.InteropServices;\npublic class Win32 {\n    [DllImport(\"user32.dll\")] public static extern bool SetForegroundWindow(IntPtr hWnd);\n    [DllImport(\"user32.dll\")] public static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, int dwExtraInfo);\n    [DllImport(\"user32.dll\")] public static extern IntPtr GetForegroundWindow();\n    [DllImport(\"user32.dll\")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);\n    public const uint KEYEVENTF_KEYUP = 0x0002;\n    public const byte VK_CONTROL = 0x11;\n    public const byte VK_E = 0x45;\n}\n\"@\n\n# ── Auth helpers ──────────────────────────────────────────────────\nfunction Get-Auth {\n    $body = @{ email = $Email; password = $Password } | ConvertTo-Json\n    $res = Invoke-RestMethod \"$Url/auth/v1/token?grant_type=password\" `\n        -Method Post `\n        -Headers @{ \"apikey\" = $AnonKey; \"Content-Type\" = \"application/json\" } `\n        -Body $body -ErrorAction Stop\n    return $res\n}\n\nfunction New-Headers($jwt) {\n    return @{\n        \"apikey\"        = $AnonKey\n        \"Authorization\" = \"Bearer $jwt\"\n        \"Content-Type\"  = \"application/json\"\n        \"Prefer\"        = \"resolution=merge-duplicates\"\n    }\n}\n\n# ── Upload single file ────────────────────────────────────────────\nfunction Send-Report($filePath, $headers) {\n    $text   = [IO.File]::ReadAllText($filePath, [Text.Encoding]::UTF8)\n    $parsed = $text | ConvertFrom-Json\n    $accountNumber = [long]$parsed.account\n    $filename = [IO.Path]::GetFileName($filePath)\n    $body = @{\n        p_account_number = $accountNumber\n        p_filename       = $filename\n        p_data           = $parsed\n    } | ConvertTo-Json -Depth 20 -Compress\n    Invoke-RestMethod \"$Url/rest/v1/rpc/upsert_report\" `\n        -Method Post -Headers $headers -Body $body -ErrorAction Stop | Out-Null\n    Write-Host \"[OK] $filename (account: $accountNumber)\"\n}\n\n# ── AutoTrading toggle helpers ────────────────────────────────────\nfunction Get-TradingStates($headers) {\n    try {\n        $getHeaders = @{ \"apikey\" = $AnonKey; \"Authorization\" = $headers[\"Authorization\"] }\n        $data = Invoke-RestMethod \"$Url/rest/v1/ea_controls?select=account_number,enabled\" `\n            -Method Get -Headers $getHeaders -ErrorAction Stop\n        $states = @{}\n        foreach ($row in $data) { $states[[string]$row.account_number] = [bool]$row.enabled }\n        return $states\n    } catch {\n        Write-Warning \"[AutoTrading] Failed to read states: $($_.Exception.Message)\"\n        return $null\n    }\n}\n\nfunction Get-ActualTradingState($accountNumber) {\n    $jsonPath = Join-Path $Folder \"mt4_report_$accountNumber.json\"\n    if (-not (Test-Path $jsonPath)) { return $null }\n    try {\n        $data = [IO.File]::ReadAllText($jsonPath, [Text.Encoding]::UTF8) | ConvertFrom-Json\n        if ($data.PSObject.Properties.Name -contains 'autoTrading') {\n            return [bool]$data.autoTrading\n        }\n        return $null\n    }\n    catch {\n        return $null\n    }\n}\n\nfunction Send-AutoTradingToggle($accountNumber) {\n    $allMt = @(Get-Process | Where-Object {\n        $_.MainWindowHandle -ne [IntPtr]::Zero -and\n        $_.ProcessName -match '^terminal'\n    })\n    if ($allMt.Count -eq 0) {\n        Write-Warning \"[AutoTrading] No MetaTrader windows found\"\n        return\n    }\n    # 口座番号でウィンドウタイトルを検索、見つからなければフォールバック\n    $targets = @($allMt | Where-Object { $_.MainWindowTitle -match \"\\b$accountNumber\\b\" })\n    if ($targets.Count -eq 0) {\n        if ($allMt.Count -eq 1) {\n            $targets = $allMt\n            Write-Host \"[AutoTrading] Account ${accountNumber}: title match failed, using only MT window\"\n        } else {\n            Write-Warning \"[AutoTrading] Cannot identify window for account ${accountNumber} ($($allMt.Count) windows open)\"\n            return\n        }\n    }\n    $prev = [Win32]::GetForegroundWindow()\n    foreach ($proc in $targets) {\n        $hwnd = $proc.MainWindowHandle\n        [Win32]::ShowWindow($hwnd, 1) | Out-Null\n        [Win32]::SetForegroundWindow($hwnd) | Out-Null\n        Start-Sleep -Milliseconds 150\n        [Win32]::keybd_event([Win32]::VK_CONTROL, 0, 0, 0)\n        [Win32]::keybd_event([Win32]::VK_E, 0, 0, 0)\n        [Win32]::keybd_event([Win32]::VK_E, 0, [Win32]::KEYEVENTF_KEYUP, 0)\n        [Win32]::keybd_event([Win32]::VK_CONTROL, 0, [Win32]::KEYEVENTF_KEYUP, 0)\n        Start-Sleep -Milliseconds 150\n    }\n    if ($prev -ne [IntPtr]::Zero) { [Win32]::SetForegroundWindow($prev) | Out-Null }\n    Write-Host \"[AutoTrading] Ctrl+E sent to account $accountNumber ($($targets.Count) window(s))\"\n}\n\ntry {\n    # ── Initial sign-in ───────────────────────────────────────────\n    $auth        = Get-Auth\n    $jwt         = $auth.access_token\n    $tokenExpiry = (Get-Date).AddSeconds($auth.expires_in - 300)\n    $headers     = New-Headers $jwt\n    Write-Host \"[Auth] Signed in as $Email\"\n\n    # ── Initial upload of all existing files ─────────────────────\n    if (Test-Path $Folder) {\n        $files = Get-ChildItem -Path $Folder -Filter \"mt4_report_*.json\" -ErrorAction SilentlyContinue\n        foreach ($file in $files) {\n            try   { Send-Report $file.FullName $headers }\n            catch { Write-Warning \"[NG] $($file.Name): $($_.Exception.Message)\" }\n        }\n    } else {\n        New-Item -ItemType Directory -Path $Folder -Force | Out-Null\n    }\n\n    # ── Ctrl+E 送信後のクールダウン（EA が JSON を更新するまで待つ） ──\n    $ctrlECooldown = @{}  # { accountNumber: datetime }\n\n    # ── FileSystemWatcher ─────────────────────────────────────────\n    $watcher = New-Object System.IO.FileSystemWatcher\n    $watcher.Path   = $Folder\n    $watcher.Filter = \"mt4_report_*.json\"\n    $watcher.NotifyFilter = [IO.NotifyFilters]'LastWrite'\n    $watcher.EnableRaisingEvents = $true\n\n    # Debounce: track last upload time per file (avoid double-fire)\n    $lastUpload = @{}\n\n    Write-Host \"[Watch] Monitoring $Folder ...\"\n\n    while ($true) {\n        # Token refresh (5 min before expiry)\n        if ((Get-Date) -gt $tokenExpiry) {\n            try {\n                $auth        = Get-Auth\n                $jwt         = $auth.access_token\n                $tokenExpiry = (Get-Date).AddSeconds($auth.expires_in - 300)\n                $headers     = New-Headers $jwt\n                Write-Host \"[Auth] Token refreshed\"\n            } catch {\n                Write-Warning \"[Auth] Token refresh failed: $($_.Exception.Message)\"\n            }\n        }\n\n        # AutoTrading 状態同期（希望値 vs JSON実際値）\n        $desired = Get-TradingStates $headers\n        if ($desired -ne $null) {\n            foreach ($acct in $desired.Keys) {\n                $desiredState = $desired[$acct]\n                $actualState  = Get-ActualTradingState $acct\n                if ($actualState -eq $null) { continue }  # JSON に autoTrading フィールドなし\n\n                if ($actualState -ne $desiredState) {\n                    # クールダウン中はスキップ（Ctrl+E 送信後 EA が JSON 更新するまで待つ）\n                    $lastSent = $ctrlECooldown[$acct]\n                    if ($lastSent -ne $null -and ((Get-Date) - $lastSent).TotalSeconds -lt 15) { continue }\n\n                    Write-Host \"[AutoTrading] Account ${acct}: actual=$actualState desired=$desiredState -> Ctrl+E\"\n                    Send-AutoTradingToggle $acct\n                    $ctrlECooldown[$acct] = Get-Date\n                }\n            }\n        }\n\n        # Wait up to 5 seconds for a file change\n        $change = $watcher.WaitForChanged([IO.WatcherChangeTypes]::Changed, 5000)\n        if ($change.TimedOut) { continue }\n\n        $name = $change.Name\n        $now  = [long]((Get-Date) - [datetime]'1970-01-01').TotalSeconds\n\n        # Debounce: skip if same file uploaded within last 2 seconds\n        if ($lastUpload.ContainsKey($name) -and ($now - $lastUpload[$name]) -lt 2) { continue }\n        $lastUpload[$name] = $now\n\n        # Wait briefly for the file write to complete\n        Start-Sleep -Milliseconds 500\n\n        $filePath = Join-Path $Folder $name\n        try   { Send-Report $filePath $headers }\n        catch { Write-Warning \"[NG] $name : $($_.Exception.Message)\" }\n    }\n} finally {\n    if ($watcher) { $watcher.Dispose() }\n    $mutex.ReleaseMutex()\n}\n"
export const RUN_VBS_CONTENT  = "' Silent launcher for sync-to-supabase.ps1\n' sync-to-supabase.ps1 / sync-config.json と同じフォルダに置いてください\nDim WshShell, scriptDir, ps1Path\nSet WshShell = CreateObject(\"WScript.Shell\")\nscriptDir = Left(WScript.ScriptFullName, InStrRev(WScript.ScriptFullName, \"\\\"))\nps1Path = scriptDir & \"sync-to-supabase.ps1\"\nWshShell.Run \"powershell.exe -NonInteractive -ExecutionPolicy Bypass -File \"\"\" & ps1Path & \"\"\"\", 0, False\nSet WshShell = Nothing\n"
